mapper.select:
SELECT


INNER JOIN content_favorite cf ON cf.post_id = cp.id
WHERE cf.user_id = #{userId}
  AND 
ORDER BY cf.create_time DESC, cp.id DESC
LIMIT #{limit}

SELECT


INNER JOIN content_view_history vh ON vh.post_id = cp.id
WHERE vh.user_id = #{userId}
  AND 
ORDER BY vh.view_time DESC, cp.id DESC
LIMIT #{limit}
